// Code generated by Speakeasy (https://speakeasy.com). DO NOT EDIT.

// Package forms asks the questions behind the CLI's guided setup: pages of
// text, secret, JSON, choice and yes/no fields. Terminals that can redraw get
// an interactive form; everything else gets plain line prompts.
package forms

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"charm.land/bubbles/v2/textarea"
	"charm.land/bubbles/v2/textinput"
	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"
	"golang.org/x/term"
)

// ErrUserAborted is returned by Run when the user cancels with ctrl+c.
var ErrUserAborted = errors.New("user aborted")

var (
	accent   = lipgloss.Color("#38BDF8")
	dimmed   = lipgloss.Color("#64748B")
	subtle   = lipgloss.Color("#475569")
	errColor = lipgloss.Color("#F87171")
)

type fieldKind int

const (
	kindInput fieldKind = iota
	kindText
	kindSelect
	kindConfirm
)

// Option is a choice in a select field: Label is shown, Value is stored.
type Option struct {
	Label string
	Value string
}

// NewOption returns a select option.
func NewOption(label, value string) Option {
	return Option{Label: label, Value: value}
}

// Field is one question. Its answer is written to the variable passed to the
// constructor as the user edits it.
type Field struct {
	kind        fieldKind
	title       string
	description string
	validate    func(string) error
	err         error

	text   *string // input, text and select answers
	yes    *bool   // confirm answer
	secret bool

	options []Option
	cursor  int

	input textinput.Model
	area  textarea.Model
}

// NewInput asks for a single line of text, starting from *value.
func NewInput(value *string) *Field {
	in := textinput.New()
	in.SetValue(*value)
	return &Field{kind: kindInput, text: value, input: in}
}

// NewText asks for multi-line text such as JSON, starting from *value.
// alt+enter or ctrl+j inserts a newline; enter moves on.
func NewText(value *string) *Field {
	area := textarea.New()
	area.ShowLineNumbers = false
	area.Prompt = ""
	area.KeyMap.InsertNewline.SetKeys("alt+enter", "ctrl+j")
	area.SetValue(*value)
	return &Field{kind: kindText, text: value, area: area}
}

// NewSelect asks for one of options, starting at the option matching *value.
func NewSelect(value *string, options ...Option) *Field {
	f := &Field{kind: kindSelect, text: value, options: options}
	for i, o := range options {
		if o.Value == *value {
			f.cursor = i
			break
		}
	}
	if len(options) > 0 {
		*value = options[f.cursor].Value
	}
	return f
}

// NewConfirm asks a yes/no question, starting from *value.
func NewConfirm(value *bool) *Field {
	return &Field{kind: kindConfirm, yes: value}
}

// Title sets the question.
func (f *Field) Title(title string) *Field { f.title = title; return f }

// Description sets the hint shown under the question.
func (f *Field) Description(description string) *Field { f.description = description; return f }

// Placeholder sets the text shown while an input is empty.
func (f *Field) Placeholder(placeholder string) *Field {
	f.input.Placeholder = placeholder
	return f
}

// Password hides what is typed into an input.
func (f *Field) Password() *Field {
	f.secret = true
	f.input.EchoMode = textinput.EchoPassword
	return f
}

// Validate rejects answers before the form moves past the field.
func (f *Field) Validate(validate func(string) error) *Field {
	f.validate = validate
	return f
}

func (f *Field) check() error {
	if f.validate == nil || f.text == nil {
		return nil
	}
	return f.validate(*f.text)
}

func (f *Field) focus() tea.Cmd {
	switch f.kind {
	case kindInput:
		return f.input.Focus()
	case kindText:
		return f.area.Focus()
	}
	return nil
}

func (f *Field) blur() {
	switch f.kind {
	case kindInput:
		f.input.Blur()
	case kindText:
		f.area.Blur()
	}
}

func (f *Field) setWidth(width int) {
	inner := max(width-4, 10)
	switch f.kind {
	case kindInput:
		f.input.SetWidth(inner - lipgloss.Width(f.input.Prompt) - 1)
	case kindText:
		f.area.SetWidth(inner)
	}
}

// update applies a message to the focused field. advance reports that the
// key also answered the question (y or n on a confirm).
func (f *Field) update(msg tea.Msg) (cmd tea.Cmd, advance bool) {
	key, isKey := msg.(tea.KeyPressMsg)
	if isKey {
		f.err = nil
	}
	switch f.kind {
	case kindInput:
		f.input, cmd = f.input.Update(msg)
		*f.text = f.input.Value()
	case kindText:
		f.area, cmd = f.area.Update(msg)
		*f.text = f.area.Value()
	case kindSelect:
		if !isKey || len(f.options) == 0 {
			return nil, false
		}
		n := len(f.options)
		switch key.String() {
		case "up", "k", "ctrl+p":
			f.cursor = (f.cursor - 1 + n) % n
		case "down", "j", "ctrl+n":
			f.cursor = (f.cursor + 1) % n
		case "home", "g":
			f.cursor = 0
		case "end", "G":
			f.cursor = n - 1
		}
		*f.text = f.options[f.cursor].Value
	case kindConfirm:
		if !isKey {
			return nil, false
		}
		switch key.String() {
		case "left", "right", "h", "l":
			*f.yes = !*f.yes
		case "y", "Y":
			*f.yes = true
			return nil, true
		case "n", "N":
			*f.yes = false
			return nil, true
		}
	}
	return cmd, false
}

// Page is a set of fields shown together under an optional heading.
type Page struct {
	title  string
	fields []*Field
}

// NewPage groups fields onto one screen.
func NewPage(title string, fields ...*Field) *Page {
	return &Page{title: title, fields: fields}
}

// Form steps through pages of fields. enter and tab move forward, shift+tab
// moves back, and enter on the last field submits.
type Form struct {
	pages      []*Page
	page       int
	field      int
	accessible bool
	width      int
	height     int
	finished   bool
	aborted    bool
}

// New returns a form over pages. Dumb terminals default to line prompts.
func New(pages ...*Page) *Form {
	f := &Form{pages: pages, accessible: os.Getenv("TERM") == "dumb"}
	f.resize(terminalWidth(), 0)
	return f
}

// Accessible switches between the interactive form and line prompts.
func (f *Form) Accessible(on bool) *Form {
	f.accessible = on
	return f
}

func terminalWidth() int {
	if width, _, err := term.GetSize(int(os.Stdout.Fd())); err == nil && width > 0 {
		return width
	}
	return 80
}

// Run asks every question and returns once the form is submitted. Answers are
// written to the variables bound to each field.
func (f *Form) Run() error {
	if f.empty() {
		return nil
	}
	if f.accessible {
		f.prompt(os.Stdout, os.Stdin)
		return nil
	}
	if _, err := tea.NewProgram(f, tea.WithOutput(os.Stderr)).Run(); err != nil {
		if errors.Is(err, tea.ErrInterrupted) {
			return ErrUserAborted
		}
		return fmt.Errorf("form: %w", err)
	}
	if f.aborted {
		return ErrUserAborted
	}
	return nil
}

func (f *Form) empty() bool {
	for _, p := range f.pages {
		if len(p.fields) > 0 {
			return false
		}
	}
	return true
}

func (f *Form) resize(width, height int) {
	f.width, f.height = width, height
	for _, p := range f.pages {
		for _, field := range p.fields {
			field.setWidth(width)
		}
	}
}

func (f *Form) current() *Field {
	return f.pages[f.page].fields[f.field]
}

func (f *Form) onLastField() bool {
	return f.page == len(f.pages)-1 && f.field == len(f.pages[f.page].fields)-1
}

// step moves the focus by one field across page boundaries, skipping empty
// pages. It reports false when there is no field in that direction.
func (f *Form) step(delta int) bool {
	page, field := f.page, f.field+delta
	for {
		switch {
		case field < 0:
			page--
			if page < 0 {
				return false
			}
			field = len(f.pages[page].fields) - 1
			continue
		case field >= len(f.pages[page].fields):
			page++
			if page >= len(f.pages) {
				return false
			}
			field = 0
			continue
		}
		f.page, f.field = page, field
		return true
	}
}

// Init implements [tea.Model].
func (f *Form) Init() tea.Cmd {
	for f.field >= len(f.pages[f.page].fields) {
		f.page++
	}
	return tea.Batch(f.current().focus(), tea.RequestWindowSize)
}

// Update implements [tea.Model].
func (f *Form) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		f.resize(msg.Width, msg.Height)
		return f, nil
	case tea.KeyPressMsg:
		switch msg.String() {
		case "ctrl+c":
			f.aborted = true
			return f, tea.Quit
		case "shift+tab":
			return f, f.move(-1)
		case "tab":
			if f.onLastField() {
				return f, nil
			}
			return f, f.forward()
		case "enter":
			return f, f.forward()
		}
	}
	cmd, advance := f.current().update(msg)
	if advance {
		return f, tea.Batch(cmd, f.forward())
	}
	return f, cmd
}

// forward validates the focused field, then moves on or submits.
func (f *Form) forward() tea.Cmd {
	cur := f.current()
	if cur.err = cur.check(); cur.err != nil {
		return nil
	}
	if f.onLastField() {
		f.finished = true
		return tea.Quit
	}
	return f.move(1)
}

func (f *Form) move(delta int) tea.Cmd {
	prev := f.current()
	if !f.step(delta) {
		return nil
	}
	prev.blur()
	return f.current().focus()
}

// View implements [tea.Model].
func (f *Form) View() tea.View {
	if f.finished || f.aborted {
		return tea.NewView("")
	}
	return tea.NewView(f.render())
}

func (f *Form) render() string {
	page := f.pages[f.page]
	var b strings.Builder
	if page.title != "" {
		b.WriteString(lipgloss.NewStyle().Foreground(accent).Bold(true).Render(page.title) + "\n\n")
	}
	for i, field := range page.fields {
		if i > 0 {
			b.WriteString("\n\n")
		}
		b.WriteString(f.renderField(field, i == f.field))
	}
	return b.String()
}

func (f *Form) renderField(field *Field, focused bool) string {
	inner := max(f.width-4, 10)
	bar, title := subtle, lipgloss.NewStyle().Foreground(dimmed)
	if focused {
		bar, title = accent, lipgloss.NewStyle().Foreground(accent).Bold(true)
	}
	lines := []string{}
	if field.title != "" {
		lines = append(lines, title.Render(lipgloss.Wrap(field.title, inner, " ")))
	}
	if field.description != "" {
		lines = append(lines, lipgloss.NewStyle().Foreground(subtle).Italic(true).Render(lipgloss.Wrap(field.description, inner, " ")))
	}
	switch field.kind {
	case kindInput:
		lines = append(lines, field.input.View())
	case kindText:
		lines = append(lines, field.area.View())
	case kindSelect:
		lines = append(lines, f.renderOptions(field, focused))
	case kindConfirm:
		lines = append(lines, renderButtons(*field.yes, focused))
	}
	if field.err != nil {
		lines = append(lines, lipgloss.NewStyle().Foreground(errColor).Render("! "+field.err.Error()))
	}
	return lipgloss.NewStyle().
		BorderStyle(lipgloss.ThickBorder()).BorderLeft(true).BorderForeground(bar).
		PaddingLeft(1).
		Render(strings.Join(lines, "\n"))
}

// renderOptions shows a window of options around the cursor that fits the
// terminal height.
func (f *Form) renderOptions(field *Field, focused bool) string {
	rows := len(field.options)
	if f.height > 0 {
		rows = min(rows, max(3, f.height-8))
	}
	start := min(max(field.cursor-rows/2, 0), len(field.options)-rows)
	picked := lipgloss.NewStyle().Foreground(dimmed)
	if focused {
		picked = lipgloss.NewStyle().Foreground(accent).Bold(true)
	}
	var lines []string
	for i := start; i < start+rows; i++ {
		if i == field.cursor {
			lines = append(lines, picked.Render("> "+field.options[i].Label))
		} else {
			lines = append(lines, "  "+field.options[i].Label)
		}
	}
	if rows < len(field.options) {
		lines = append(lines, lipgloss.NewStyle().Foreground(subtle).Render(fmt.Sprintf("  %d/%d", field.cursor+1, len(field.options))))
	}
	return strings.Join(lines, "\n")
}

func renderButtons(yes, focused bool) string {
	on := lipgloss.NewStyle().Padding(0, 2).Foreground(lipgloss.Color("#FFFFFF")).Background(subtle)
	if focused {
		on = on.Background(accent)
	}
	off := lipgloss.NewStyle().Padding(0, 2).Foreground(dimmed)
	if yes {
		return on.Render("Yes") + " " + off.Render("No")
	}
	return off.Render("Yes") + " " + on.Render("No")
}

// prompt asks every question as a plain line prompt. Blank answers keep the
// current value; end of input leaves the remaining answers unchanged.
func (f *Form) prompt(w io.Writer, r io.Reader) {
	in := bufio.NewReader(r)
	for _, page := range f.pages {
		for _, field := range page.fields {
			if !field.ask(w, r, in) {
				fmt.Fprintln(w)
				return
			}
			fmt.Fprintln(w)
		}
	}
}

// ask prompts for one field until the answer is valid. It reports false at
// end of input.
func (f *Field) ask(w io.Writer, raw io.Reader, in *bufio.Reader) bool {
	if f.title != "" {
		fmt.Fprintln(w, f.title)
	}
	if f.description != "" {
		fmt.Fprintln(w, f.description)
	}
	switch f.kind {
	case kindSelect:
		for i, o := range f.options {
			fmt.Fprintf(w, "  %d. %s\n", i+1, o.Label)
		}
	}
	for {
		switch f.kind {
		case kindSelect:
			fmt.Fprintf(w, "Choose 1-%d [%d]: ", len(f.options), f.cursor+1)
		case kindConfirm:
			if *f.yes {
				fmt.Fprint(w, "[Y/n]: ")
			} else {
				fmt.Fprint(w, "[y/N]: ")
			}
		default:
			fmt.Fprint(w, "> ")
		}
		line, ok := readAnswer(w, raw, in, f.secret)
		if !ok {
			return false
		}
		if msg := f.answer(line); msg != "" {
			fmt.Fprintln(w, msg)
			continue
		}
		return true
	}
}

// answer applies a typed line, returning a message when it must be re-asked.
func (f *Field) answer(line string) string {
	line = strings.TrimSpace(line)
	switch f.kind {
	case kindSelect:
		if line == "" {
			return ""
		}
		n, err := strconv.Atoi(line)
		if err != nil || n < 1 || n > len(f.options) {
			return fmt.Sprintf("Enter a number from 1 to %d.", len(f.options))
		}
		f.cursor = n - 1
		*f.text = f.options[f.cursor].Value
	case kindConfirm:
		switch strings.ToLower(line) {
		case "":
		case "y", "yes":
			*f.yes = true
		case "n", "no":
			*f.yes = false
		default:
			return "Answer y or n."
		}
	default:
		value := *f.text
		if line != "" {
			value = line
		}
		if f.validate != nil {
			if err := f.validate(value); err != nil {
				return err.Error()
			}
		}
		*f.text = value
	}
	return ""
}

// readAnswer reads one line, without echo for secrets typed at a terminal.
func readAnswer(w io.Writer, raw io.Reader, in *bufio.Reader, secret bool) (string, bool) {
	if file, ok := raw.(*os.File); ok && secret && term.IsTerminal(int(file.Fd())) {
		b, err := term.ReadPassword(int(file.Fd()))
		fmt.Fprintln(w)
		return string(b), err == nil
	}
	line, err := in.ReadString('\n')
	if err != nil && line == "" {
		return "", false
	}
	return strings.TrimRight(line, "\r\n"), true
}
